["thumb_01_side_inn_l"]={driver="thumb",Rotation={x=-0.0927699214462,y=-0.664078955322,z=0.151123256502,w=-0.726329569904},Translation={x=2.18299102783,y=0.0416638031602,z=3.27708268166}},
["thumb_02_l"]={driver="thumb",Rotation={x=0.0318398783723,y=0.0425277100138,z=0.35860821597,w=-0.931975194662},Translation={x=4.37800073624,y=7.1163958637e-07,z=-3.68520704797e-06}},
