-- Quest Touch/Touch Plus gestures through the UEVR 1.05 action contract.
-- REFERENCE is generated immediately above from the cooked SK_Player skeleton.
-- REFERENCE is the neutral pose; AUTHORED_GRASP contains decoded grab targets.
-- With the supplied OpenXR Oculus/Index binding overrides, enable capacitive_aliases:
-- AButtonTouch[Left/Right] becomes index trigger touch and BButtonTouch becomes
-- the aggregate thumb contact. No new action or native UEVR build is required.
--
-- local hands = Gestures.new(IK)
-- local controls = hands:sample(uevr.params.vr)
-- local ray = hands:apply("left", solvedWrist, controls.left, dt, setBone)
-- setBone(name, worldTransform) writes EBoneSpaces::WorldSpace on the visual.
-- Do not CopyPose over the visual after this initializes it. If CopyPose is
-- unavoidable, pass {force_reference=true} as the sixth argument every frame.
-- Call hands:reset() when replacing/clearing the poseable component.
local M={}
local fingers={"thumb","index","middle","ring","pinky"}
-- Closing blends toward the shipped grab clip rather than guessing anatomical
-- hinge axes from a palm normal. Wrist offsets and input classification stay
-- separate. The left target is a mirrored adaptation, not an authored left clip.
local action_prefix="/actions/default/in/"
local function finite(n) return type(n)=="number" and n==n and math.abs(n)<1e12 end
local function clamp(n) return math.max(0,math.min(1,n)) end

-- Explicit state mapping is independently testable without a runtime. Input
-- remains buttons/capacitive contact; UEVR1.05 does not expose per-finger
-- skeletons or continuous trigger/grip values to Lua. Index contact is carried
-- by an existing passive action only when the supplied remap is enabled.
function M.classify(side,raw)
 assert(side=="left" or side=="right","Unknown hand side")
 raw=raw or {}
 local trigger=raw.trigger==true
 local grip=raw.grip==true
 local touch=raw.thumb_touch==true
 local index_touch=raw.index_touch==true and raw.index_touch_available==true
 local state={trigger=trigger,grip=grip,thumb_touch=touch,
  ready=raw.ready~=false,thumb_touch_available=raw.thumb_touch_available==true,
  index_touch=index_touch,index_touch_available=raw.index_touch_available==true,
  touch_mapping=raw.touch_mapping or "stock",
  squeeze=side=="right" and trigger and grip}
 if side=="left" then
  state.curls={thumb=touch and 1 or 0,index=trigger and 1 or (index_touch and .48 or 0),
   middle=grip and 1 or 0,ring=grip and 1 or 0,pinky=grip and 1 or 0}
  if trigger and grip then state.gesture=touch and "fist" or "thumb_up"
  elseif grip then
   if index_touch then state.gesture=touch and "grasp" or "thumb_up"
   else state.gesture=touch and "point" or "finger_gun" end
  elseif trigger or index_touch then state.gesture="index_curl"
  else state.gesture=touch and "relaxed_palm" or "open_palm" end
  state.pointing=grip and not trigger and not index_touch
 else
  -- The right palm keeps a relaxed grasp around the rat. Both buttons make
  -- a closed fist regardless of thumb contact: this is the squeeze contract.
  state.curls={thumb=.55,index=trigger and .75 or .22,
   middle=grip and .9 or .42,ring=grip and .9 or .42,pinky=grip and .9 or .42}
  if state.squeeze then
   for _,finger in ipairs(fingers) do state.curls[finger]=1 end
   state.gesture="fist"
  elseif trigger then state.gesture="shake_grasp"
  else state.gesture="rat_grasp" end
  state.pointing=false
 end
 return state
end

function M.new(IK,options)
 assert(IK and IK.vector and IK.quaternion,"IK math dependency is required")
 options=options or {}
 local V,Q=IK.vector,IK.quaternion
 local self={reference=REFERENCE,states={},handles={},smoothing=options.smoothing or 18,
  writes=0,capacitive_aliases=options.capacitive_aliases==true,
  capabilities={thumb_touch=true,index_touch=false,analog_curl=false}}
 local function snapshot(t)
  return {Translation=V.read(t.Translation),Rotation=Q.normalize(t.Rotation),Scale3D=V.read(t.Scale3D)}
 end
 local function multiply_components(a,b) return V.new(a.x*b.x,a.y*b.y,a.z*b.z) end
 local function compose(parent,pose,rotation)
  return {Translation=V.add(parent.Translation,Q.rotate(parent.Rotation,multiply_components(pose.Translation,parent.Scale3D))),
   Rotation=Q.multiply(parent.Rotation,rotation or pose.Rotation),Scale3D=multiply_components(parent.Scale3D,pose.Scale3D)}
 end
 local function blend_rotation(a,b,t)
  a,b=Q.normalize(a),Q.normalize(b)
  local dot=a.x*b.x+a.y*b.y+a.z*b.z+a.w*b.w
  if dot<0 then b={x=-b.x,y=-b.y,z=-b.z,w=-b.w};dot=-dot end
  local x,y=1-t,t
  if dot<.9995 then
   local angle=math.acos(math.max(-1,math.min(1,dot)));local sine=math.sin(angle)
   x,y=math.sin((1-t)*angle)/sine,math.sin(t*angle)/sine
  end
  return Q.normalize({x=x*a.x+y*b.x,y=x*a.y+y*b.y,z=x*a.z+y*b.z,w=x*a.w+y*b.w})
 end
 function self:reset(side)
  if side then self.states[side]=nil else self.states={} end
 end
 function self:sample(vr)
  local sampled={}
  local xr_ok,is_openxr=pcall(vr.is_openxr)
  local use_aliases=self.capacitive_aliases and xr_ok and is_openxr==true
  self.capabilities.index_touch=use_aliases
  local function action(name,source)
   local handle=self.handles[name]
   if handle==nil then
    local ok,value=pcall(vr.get_action_handle,action_prefix..name)
    if ok and value~=nil and value~=0 then handle=value;self.handles[name]=value end
   end
   if handle==nil or handle==0 then return false,false end
   local ok,value=pcall(vr.is_action_active,handle,source)
   return ok and value==true,ok
  end
  for _,side in ipairs({"left","right"}) do
   local source_fn=side=="left" and vr.get_left_joystick_source or vr.get_right_joystick_source
   local source_ok,source=pcall(source_fn)
   local raw={ready=false}
   -- OpenXR intentionally uses source 0 for LEFT (VRRuntime::Hand::LEFT).
   -- Its C API returns an opaque pointer: sol may push nullptr as Lua nil,
   -- not numeric zero. Preserve nil when calling the pointer-taking API.
   -- A failed getter, right null source, and OpenVR null remain invalid.
   local source_valid=source_ok and source~=nil
   if source==nil or source==0 then
    source_valid=source_ok and xr_ok and is_openxr==true and side=="left"
   end
   if source_valid then
    local suffix=side=="left" and "Left" or "Right"
    local trigger,has_trigger=action("Trigger",source)
    local grip,has_grip=action("Grip",source)
    local rest,has_rest=action("ThumbrestTouch"..suffix,source)
    local a,has_a=action("AButtonTouch"..suffix,source)
    local b,has_b=action("BButtonTouch"..suffix,source)
    local apress=action("AButton"..suffix,source)
    local bpress=action("BButton"..suffix,source)
    local stickpress=action("JoystickClick",source)
    raw={trigger=trigger,grip=grip,
     thumb_touch=rest or b or (not use_aliases and a) or apress or bpress or stickpress,
     index_touch=use_aliases and a,index_touch_available=use_aliases and has_a,
     touch_mapping=use_aliases and "openxr_quest_capacitive_aliases" or "stock",
     ready=has_trigger and has_grip,
     thumb_touch_available=has_rest or has_b or (not use_aliases and has_a)}
   end
   sampled[side]=M.classify(side,raw)
  end
  return sampled
 end
 function self:apply(side,wrist,control,dt,setBone,apply_options)
  local reference=assert(REFERENCE[side],"Unknown hand side")
  assert(type(setBone)=="function","setBone callback is required")
  assert(finite(dt) and dt>=0 and dt<=1,"Invalid gesture frame delta")
  apply_options=apply_options or {}
  control=control or M.classify(side,{ready=false})
  local previous=self.states[side]
  local initial=previous==nil
  local state=previous or {curls={},written={}}
  self.states[side]=state
  local factor=1-math.exp(-self.smoothing*dt)
  local changed={}
  for _,finger in ipairs(fingers) do
   local target=control.curls and control.curls[finger] or 0
   assert(finite(target),"Nonfinite finger curl")
   target=clamp(target)
   local old=state.curls[finger]
   local current=old==nil and target or old+(target-old)*factor
   if math.abs(current-target)<1e-5 then current=target end
   state.curls[finger]=current
   changed[finger]=old==nil or math.abs(current-(state.written[finger] or -1))>1e-5
  end
  local world={[reference.wrist]=snapshot(wrist)}
  local writes=0
  for _,bone in ipairs(reference.bones) do
   local rotation=bone.Rotation
   local pose=bone
   local authored=AUTHORED_GRASP[side][bone.name]
   local driver=authored and authored.driver or bone.finger
   if authored then
    local curl=state.curls[driver]
    rotation=blend_rotation(bone.Rotation,authored.Rotation,curl)
    pose={Translation=V.add(bone.Translation,V.mul(V.sub(authored.Translation,bone.Translation),curl)),Scale3D=bone.Scale3D}
   end
   local transform=compose(assert(world[bone.parent],"Missing reference parent"),pose,rotation)
   world[bone.name]=transform
   if initial or apply_options.force_reference or (driver and changed[driver]) then
    setBone(bone.name,transform);writes=writes+1
   end
  end
  for _,finger in ipairs(fingers) do
   if changed[finger] or initial or apply_options.force_reference then state.written[finger]=state.curls[finger] end
  end
  self.writes=writes
  local suffix=side=="left" and "l" or "r"
  local index2=world["index_02_"..suffix].Translation
  local index3=world["index_03_"..suffix].Translation
  local direction=V.normalize(V.sub(index3,index2))
  local tip=V.add(index3,V.mul(direction,2.15))
  return {pointing=control.ready~=false and control.pointing==true and state.curls.index<.22 and state.curls.middle>.55,
   origin=tip,direction=direction,gesture=control.gesture,curls=state.curls,
   transforms=world,writes=writes,squeeze=control.squeeze==true,
   thumb_touch_available=control.thumb_touch_available==true,
   index_touch_available=control.index_touch_available==true}
 end
 return self
end
M.reference=REFERENCE
M.authored=AUTHORED_GRASP
return M
